import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static long powerMod(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            res = (res * base) % MOD;
            exp--;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long pwr;

        if (k == 0) {
            pwr = p - 1;
        } else if (k == 1) {
            pwr = p;
        } else {
            long x = k;
            long count = 1;
            while (x != 1) {
                x = (x * k) % p;
                count++;
            }
            pwr = (p - 1) / count;
        }

        System.out.println(powerMod(p, pwr));
        sc.close();
    }
}
